package com.bank.headcount;

import java.util.*;
import java.util.logging.*;
import static java.util.stream.Collectors.*;

public class HeadcountDemo {
    private static final Logger log = Logger.getLogger("Headcount");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Employee(1L, "Rajesh", "IT"),
            new Employee(2L, "Priya", "Finance"),
            new Employee(3L, "Amit", "IT"),
            new Employee(4L, "Sneha", "Finance"),
            new Employee(5L, "Vikram", "HR")
        );
        HeadcountService service = new HeadcountService();
        Map<String, Long> counts = service.countByDepartment(staff);
        counts.forEach((dept, n) -> log.info(() -> dept + " -> " + n));
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final Long id;
    private final String name;
    private final String department;
    Employee(Long id, String name, String department) { this.id = id; this.name = name; this.department = department; }
    String getDepartment() { return department; }
}

// ─── Would be in service/HeadcountService.java ───
class HeadcountService {
    // groupingBy + counting() keeps only a per-department tally (no lists materialised).
    Map<String, Long> countByDepartment(List<Employee> employees) {
        return employees.stream()
            .collect(groupingBy(Employee::getDepartment, TreeMap::new, counting()));
    }
}
